AND(NOT($Setup.Metadata_Activation_Settings__c.Disable_VR__c && OR(ISBLANK($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c), CONTAINS($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c, 'Account'))), RecordType.DeveloperName = $Label.QTB_AccountRecordType_Billing,

  IF( ISPICKVAL( QTB_Legal_Entity_Country__c , 'Turkey') , 

   NOT(  OR( ISPICKVAL( QTB_Invoice_Delivery_Options__c , 'e-Fatura') ,

    ISPICKVAL( QTB_Invoice_Delivery_Options__c , 'e-Arşiv') 


) ) 

 ,

 OR( ISPICKVAL( QTB_Invoice_Delivery_Options__c , 'e-Fatura') ,


 ISPICKVAL( QTB_Invoice_Delivery_Options__c , 'e-Arşiv') ) 

)


)
